/** Defers an OPEN claim until a date after the sheet's today; any other status, or a date not after today, is refused. */
public class ApplyDefer {
    public void apply(@Val Claim claim, @Val DeferUntil until, ClaimRepository repository, SheetRepository sheets)
            throws BadRequestException {
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new BadRequestException("Only an OPEN claim is deferred; this one is " + claim.getStatus());
        }
        if (!until.date().isAfter(sheets.today(claim.getSheetId()))) {
            throw new BadRequestException("A claim is deferred to a date after the sheet's today");
        }
        claim.setDeferredUntil(until.date());
        if (!repository.defer(claim)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
    }
}
=== claim/ApplyReassign.java
/**
 * Moves the claim to another person on the sheet: a steward's, and only for a DRAFT, OPEN or PENDING claim, never to its
 * own person nor to one retired before the claim's date. It keeps its number and date, loses any figure a statement
 * bound it to (live again until its new person's next statement) and is listed as its new person's newest claim.
 */
public class ApplyReassign {
    public void apply(@Val ReassignTo to, @Val Claim claim, @Val ChangedBy by, ClaimRepository repository,
            PersonRepository people, RoleRepository roles) throws BadRequestException {
        String sheetId = claim.getSheetId();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by.name()))) {
            throw new BadRequestException("Only a steward moves a claim to another person");
        }
        ClaimStatus status = claim.getStatus();
        if (status != ClaimStatus.DRAFT && !status.isOpen()) {
            throw new BadRequestException("A " + status + " claim cannot move to another person");
        }
        Person target = people.find(sheetId, to.personId());
        if (target == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        if (target.getId() == claim.getPersonId()) {
            throw new BadRequestException("The claim is already that person's");
        }
        RefuseRetiredDate.refuse(target, claim.getDate());
        Person from = people.find(sheetId, claim.getPersonId());
        if (!repository.reassign(claim, target.getId())) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
        to.moved(from == null ? "" : from.getName(), target.getName());
    }
}
=== claim/ApplyResettle.java
/**
 * A steward's re-settle of a SETTLED claim: freezes its due again at the figure it would have today as an OPEN claim bound
 * by no statement — the rate in force on the claim's date of its person's grade on that date (at least the sheet's
 * floor in force on the claim's date), with its late charge as of the sheet's today on top. Without a rate its due becomes n/a.
 */
public class ApplyResettle {
    public void apply(@Val Claim claim, @Val ChangedBy by, ClaimRepository repository, PersonRepository people,
            RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            Out<Resettled> resettled) throws BadRequestException {
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by.name()))) {
            throw new BadRequestException("Only a steward re-settles a claim");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new BadRequestException("Only a SETTLED claim is re-settled; this one is " + claim.getStatus());
        }
        LateCharge late = settings.lateCharge(claim.getSheetId(), sheets.today(claim.getSheetId()));
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal rate = person == null ? null
                : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal figure = claim.figureAt(rate, late.settings().floor(claim.getDate()), late.rounding(claim));
        BigDecimal before = claim.getSettledDue();
        BigDecimal after = late.dueAsOpen(claim, figure);
        claim.setSettledDue(after);
        if (!repository.updateStatus(claim, ClaimStatus.SETTLED)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
        resettled.set(new Resettled(before, after));
    }
}
