2	/**
3	 * Adds a DRAFT claim per pasted line, in order, for the person of that name (case and surrounding spaces ignored).
4	 * Every line is first checked as the claim form checks a new claim (person on the sheet, correction, closed period,
5	 * retirement); one refusal refuses them all before anything is written. Each added claim is recorded as CLAIM_ADDED,
6	 * then the rollup lines for what the paste moved.
7	 */
8	public class AddPastedClaims {
9	    public void add(@Val SheetResponse sheet, @Val PasteLines pasted, @Val ChangedBy by, PersonRepository people,
10	            ClaimRepository claims, SheetRepository sheets, PeriodRepository periods, SettingRepository settings,
11	            Rollup rollup, Audit audit, ClaimLog log, Out<PasteResponse> response) throws BadRequestException {
12	        LocalDate today = sheets.today(sheet.id());
13	        List<Person> persons = new ArrayList<>();
14	        int n = 0;
15	        for (PasteLine line : pasted.lines()) {
16	            n++;
17	            Person person = people.findByName(sheet.id(), line.name());
18	            if (person == null) {
19	                throw new BadRequestException("Line " + n + ": " + line.name() + " is not on this sheet");
20	            }
21	            ClaimInput input = line.input();
22	            LocalDate date = input.date() != null ? input.date() : today;
23	            try {
24	                RefuseBadCorrection.refuse(input, sheet.id(), person.getId(), claims);
25	                if (periods.closedOn(sheet.id(), date)) {
26	                    throw new BadRequestException(RefuseClosedDate.CLOSED);
27	                }
28	                RefuseRetiredDate.refuse(person, date);
29	            } catch (BadRequestException e) {
30	                throw new BadRequestException("Line " + n + ": " + e.getMessage());
31	            }
32	            persons.add(person);
33	        }
34	        RollupSnapshot before = rollup.snapshot(sheet.id());
35	        for (int i = 0; i < persons.size(); i++) {
36	            Person person = persons.get(i);
37	            ClaimInput input = pasted.lines().get(i).input();
38	            LocalDate date = input.date() != null ? input.date() : today;
39	            LocalDate dueBy = date.plusDays(settings.dated(sheet.id()).terms(person.gradeOn(date), date));
40	            Claim claim = claims.insert(sheet.id(), person.getId(), input.amount(), date, input.note(),
41	                    input.corrects(), dueBy);
42	            audit.record(ClaimAudit.line("CLAIM_ADDED", claim, by, person.getName()));
43	            log.record(claim, by);
44	        }
45	        rollup.record(sheet.id(), before, by);
46	        response.set(new PasteResponse(persons.size()));
47	    }
48	}
