60	/**
61	 * Moves the claim to the asked status, refusing a change its current status does not allow and
62	 * refusing to let the user who opened it settle it; a clerk's settle whose due is above the sheet's
63	 * clerk limit in force on its today leaves it PENDING instead (a due of n/a is within any limit; a steward settles anything). A review of a
64	 * PENDING claim is a steward's: approving settles it at its live due (never by the user who opened it), rejecting
65	 * returns it to OPEN, bound again by its last statement if that bound it. Opening records who opened it; a voided claim keeps its number. Settling
66	 * fixes the claim's due at the rate in force on the claim's date of its person's grade on that date (at least the sheet's floor in force on the claim's date) — or, while a statement binds it, at
67	 * the figure it was bound to — with its late charge as of the sheet's today frozen in on top; without a figure its due stays live.
68	 */
69	public class ApplyClaimStatus {
70	    public void apply(@Val ClaimStatus status, @Val Claim claim, ClaimRepository repository,
71	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
72	            PeriodRepository periods, @Val ChangedBy by, @Val ClaimReview review, Out<ClaimNumber> audited) throws BadRequestException {
73	        ClaimStatus from = claim.getStatus();
74	        boolean steward = Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by.name()));
75	        if (review.asked()) {
76	            if (from != ClaimStatus.PENDING) {
77	                throw new BadRequestException("Only a PENDING claim is approved or rejected; this one is " + from);
78	            }
79	            if (!steward) {
80	                throw new BadRequestException("Only a steward approves or rejects a claim");
81	            }
82	            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
83	                throw new BadRequestException("The user who opened a claim cannot approve it");
84	            }
85	        } else {
86	            if (!from.canBecome(status)) {
87	                throw new BadRequestException("A " + from + " claim cannot become " + status);
88	            }
89	            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
90	                throw new BadRequestException("The user who opened a claim cannot settle it");
91	            }
92	            if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
93	                throw new BadRequestException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
94	            }
95	        }
96	        LateCharge late = settings.lateCharge(claim.getSheetId(), sheets.today(claim.getSheetId()));
97	        BigDecimal due = status == ClaimStatus.SETTLED ? late.due(claim, dueNow(claim, people, rates, settings, late)) : null;
98	        ClaimStatus to = status;
99	        if (!review.asked() && status == ClaimStatus.SETTLED && due != null && !steward) {
100	            BigDecimal limit = late.settings().clerkLimit(late.today());
101	            if (limit != null && due.compareTo(limit) > 0) {
102	                to = ClaimStatus.PENDING; // awaits a steward's approval
103	            }
104	        }
105	        claim.setStatus(to);
106	        boolean opening = to == ClaimStatus.OPEN && !review.asked();
107	        if (opening) {
108	            claim.setOpenedBy(by.name());
109	        }
110	        if (to == ClaimStatus.SETTLED) {
111	            claim.setSettledDue(due);
112	        }
113	        if (!repository.updateStatus(claim, from)) {
114	            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
115	        }
116	        if (opening) {
117	            // Numbered only once the claim is surely moving, so a refused open uses up no number.
118	            claim.setNumber(number(claim, repository, settings, sheets, periods));
119	            repository.updateStatus(claim, to);
120	        }
121	        audited.set(new ClaimNumber(claim.getNumber()));
122	    }
123	    /**
124	     * The number an opened claim takes: while the sheet numbers by period and its today is on or after that setting's
125	     * date, the next within the claim's period (by its date) as {@code <period name>-<n>}, or {@code X-<n>} in no period;
126	     * otherwise the sheet's next.
127	     */
128	    private static String number(Claim claim, ClaimRepository repository, SettingRepository settings,
129	            SheetRepository sheets, PeriodRepository periods) {
130	        String sheetId = claim.getSheetId();
131	        java.time.LocalDate from = settings.periodNumberingFrom(sheetId);
132	        if (from == null || sheets.today(sheetId).isBefore(from)) {
133	            return String.valueOf(repository.nextNumber(sheetId));
134	        }
135	        Period period = periods.on(sheetId, claim.getDate());
136	        return period == null ? "X-" + repository.nextNumber(sheetId, "X")
137	                : period.name() + "-" + repository.nextNumber(sheetId, String.valueOf(period.id()));
138	    }
139	    /** The figure a statement binds the claim to (not while PENDING), else the claim's amount times its person's grade's rate on the claim's date, rounded as the claim rounds by the sheet's policy date and at least the sheet's floor (a correction has none); null when there is no rate. */
140	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates,
141	            SettingRepository settings, LateCharge late) {
142	        if (claim.isBound()) {
143	            return claim.getStatedDue();
144	        }
145	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
146	        BigDecimal rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
147	        return claim.figureAt(rate, late.settings().floor(claim.getDate()), late.rounding(claim));
148	    }
149	}
