168	/**
169	 * Moves the claim to another person on the sheet: a steward's, and only for a DRAFT, OPEN or PENDING claim, never to its
170	 * own person nor to one retired before the claim's date. It keeps its number and date, loses any figure a statement
171	 * bound it to (live again until its new person's next statement) and is listed as its new person's newest claim.
172	 */
173	public class ApplyReassign {
174	    public void apply(@Val ReassignTo to, @Val Claim claim, @Val ChangedBy by, ClaimRepository repository,
175	            PersonRepository people, RoleRepository roles) throws BadRequestException {
176	        String sheetId = claim.getSheetId();
177	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by.name()))) {
178	            throw new BadRequestException("Only a steward moves a claim to another person");
179	        }
180	        ClaimStatus status = claim.getStatus();
181	        if (status != ClaimStatus.DRAFT && !status.isOpen()) {
182	            throw new BadRequestException("A " + status + " claim cannot move to another person");
183	        }
184	        Person target = people.find(sheetId, to.personId());
185	        if (target == null) {
186	            throw new BadRequestException("No such person on this sheet");
187	        }
188	        if (target.getId() == claim.getPersonId()) {
189	            throw new BadRequestException("The claim is already that person's");
190	        }
191	        RefuseRetiredDate.refuse(target, claim.getDate());
192	        Person from = people.find(sheetId, claim.getPersonId());
193	        if (!repository.reassign(claim, target.getId())) {
194	            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
195	        }
196	        to.moved(from == null ? "" : from.getName(), target.getName());
197	    }
198	}
