200	/**
201	 * A steward's re-settle of a SETTLED claim: freezes its due again at the figure it would have today as an OPEN claim bound
202	 * by no statement — the rate in force on the claim's date of its person's grade on that date (at least the sheet's
203	 * floor in force on the claim's date), with its late charge as of the sheet's today on top. Without a rate its due becomes n/a.
204	 */
205	public class ApplyResettle {
206	    public void apply(@Val Claim claim, @Val ChangedBy by, ClaimRepository repository, PersonRepository people,
207	            RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
208	            Out<Resettled> resettled) throws BadRequestException {
209	        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by.name()))) {
210	            throw new BadRequestException("Only a steward re-settles a claim");
211	        }
212	        if (claim.getStatus() != ClaimStatus.SETTLED) {
213	            throw new BadRequestException("Only a SETTLED claim is re-settled; this one is " + claim.getStatus());
214	        }
215	        LateCharge late = settings.lateCharge(claim.getSheetId(), sheets.today(claim.getSheetId()));
216	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
217	        BigDecimal rate = person == null ? null
218	                : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
219	        BigDecimal figure = claim.figureAt(rate, late.settings().floor(claim.getDate()), late.rounding(claim));
220	        BigDecimal before = claim.getSettledDue();
221	        BigDecimal after = late.dueAsOpen(claim, figure);
222	        claim.setSettledDue(after);
223	        if (!repository.updateStatus(claim, ClaimStatus.SETTLED)) {
224	            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
225	        }
226	        resettled.set(new Resettled(before, after));
227	    }
228	}
