265	/** The rule for a claim's amount, shared by every form that enters one. */
266	public final class ClaimAmount {
267	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,12}(\\.\\d{1,2})?");
268	    private ClaimAmount() {
269	    }
270	    /** A claim's amount: required; a number with up to two decimals, 0.00 or more. */
271	    public static BigDecimal of(String typed) throws BadRequestException {
272	        String amount = typed == null ? "" : typed.trim();
273	        if (amount.isEmpty()) {
274	            throw new BadRequestException("Enter an amount");
275	        }
276	        if (!AMOUNT.matcher(amount).matches()) {
277	            throw new BadRequestException("An amount is a number, 0.00 or more, with up to two decimals");
278	        }
279	        return new BigDecimal(amount).setScale(2);
280	    }
281	    /** A claim's amount on the claim form: as {@link #of}, or below 0.00 for a correction. */
282	    public static BigDecimal signed(String typed) throws BadRequestException {
283	        String amount = typed == null ? "" : typed.trim();
284	        if (amount.startsWith("-")) {
285	            BigDecimal magnitude = of(amount.substring(1));
286	            if (magnitude.signum() == 0) {
287	                throw new BadRequestException("An amount is a number with up to two decimals");
288	            }
289	            return magnitude.negate();
290	        }
291	        return of(amount);
292	    }
293	}
