687	/**
688	 * A claim's status: DRAFT → OPEN → SETTLED, and a DRAFT, OPEN or PENDING claim may become VOID. A clerk's settle above
689	 * the clerk limit leaves an OPEN claim PENDING; a steward's review then approves it (SETTLED) or rejects it (OPEN).
690	 */
691	public enum ClaimStatus {
692	    DRAFT, OPEN, PENDING, SETTLED, VOID;
693	    /** Whether a claim in this status may move to {@code next} by an open, settle or void (not a review). */
694	    public boolean canBecome(ClaimStatus next) {
695	        return switch (next) {
696	            case OPEN -> this == DRAFT;
697	            case SETTLED, PENDING -> this == OPEN;
698	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
699	            case DRAFT -> false;
700	        };
701	    }
702	    /** Whether a claim in this status counts toward claimed, due and every total. */
703	    public boolean counts() {
704	        return this == OPEN || this == PENDING || this == SETTLED;
705	    }
