743	/**
744	 * Opens each selected claim in list order — the people in the order they were added, each one's claims newest
745	 * first — so they are numbered in that order. Each is opened exactly as opening it alone would (the same refusals,
746	 * the same audit and rollup lines); one that cannot be opened is left as it is and counted as refused.
747	 */
748	public class OpenClaims {
749	    public void open(@Val SheetResponse sheet, @Val BulkOpenIds selected, @Val ChangedBy by, ClaimRepository claims,
750	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
751	            SheetRepository sheets, PeriodRepository periods, Rollup rollup, Audit audit, ClaimLog log,
752	            Out<BulkOpenResponse> result) {
753	        int opened = 0;
754	        ApplyClaimStatus apply = new ApplyClaimStatus();
755	        RefuseClosedClaim closed = new RefuseClosedClaim();
756	        RecordClaimStatus record = new RecordClaimStatus();
757	        for (Person person : people.list(sheet.id())) {
758	            for (Claim claim : claims.listOf(sheet.id(), person.getId())) {
759	                if (!selected.ids().contains(claim.getId())) {
760	                    continue;
761	                }
762	                try {
763	                    closed.check(claim, periods);
764	                    RollupSnapshot before = rollup.snapshot(sheet.id());
765	                    ClaimNumber[] number = new ClaimNumber[1];
766	                    Out<ClaimNumber> audited = value -> number[0] = value;
767	                    apply.apply(ClaimStatus.OPEN, claim, claims, people, rates, roles, settings, sheets, periods, by, ClaimReview.NONE, audited);
768	                    record.record(claim, number[0], by, ClaimReview.NONE, people, audit, log);
769	                    rollup.record(sheet.id(), before, by);
770	                    opened++;
771	                } catch (BadRequestException refused) {
772	                    // left as it is
773	                }
774	            }
775	        }
776	        // A selected id not on this sheet's list cannot be opened either.
777	        result.set(new BulkOpenResponse(opened, selected.ids().size() - opened));
778	    }
779	}
