50	    public RollupSnapshot snapshot(String sheetId) {
51	        LocalDate today = sheets.today(sheetId);
52	        List<Rate> sheetRates = rates.list(sheetId);
53	        List<Claim> sheetClaims = claims.list(sheetId);
54	        LateCharge late = settings.lateCharge(sheetId, today);
55	        BigDecimal cap = late.settings().cap(today);
56	        Map<Long, Figures> figures = new LinkedHashMap<>();
57	        BigDecimal claimedTotal = ZERO;
58	        BigDecimal dueTotal = ZERO;
59	        BigDecimal overdueTotal = ZERO;
60	        for (Person p : people.list(sheetId)) {
61	            BigDecimal claimed = ZERO;
62	            BigDecimal due = ZERO;
63	            BigDecimal overdue = ZERO;
64	            boolean kept = false;
65	            for (Claim c : sheetClaims) {
66	                if (c.getPersonId() != p.getId() || !counts(c, p, today)) {
67	                    continue;
68	                }
69	                claimed = claimed.add(c.getAmount().setScale(2));
70	                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
71	                String grade = p.gradeOn(c.getDate());
72	                BigDecimal figure = late.due(c, figure(c, grade, sheetRates, late));
73	                // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
74	                // dated on or before today, whose rate may have ended since.
75	                kept |= figure != null && (!grade.equals(p.getGrade()) || !c.getDate().isAfter(today));
76	                if (figure != null) {
77	                    due = due.add(figure);
78	                    if (overdue(c, today)) {
79	                        overdue = overdue.add(figure);
80	                    }
81	                }
82	            }
83	            BigDecimal personDue = SettingRepository.capped(
84	                    kept || rateOn(sheetRates, p.getGrade(), today) != null ? due : null, cap);
85	            figures.put(p.getId(), new Figures(p.getName(), claimed, personDue, overdue));
86	            claimedTotal = claimedTotal.add(claimed);
87	            overdueTotal = overdueTotal.add(overdue);
88	            if (personDue != null) {
89	                dueTotal = dueTotal.add(personDue);
90	            }
91	        }
92	        return new RollupSnapshot(figures, claimedTotal, dueTotal, overdueTotal);
93	    }
