105	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
106	        List<Rate> sheetRates = rates.list(sheetId);
107	        LocalDate today = sheets.today(sheetId);
108	        LateCharge late = settings.lateCharge(sheetId, today);
109	        Map<Long, Person> byId = new LinkedHashMap<>();
110	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
111	        for (Person p : people.list(sheetId)) {
112	            byId.put(p.getId(), p);
113	            totals.put(p.getId(), ZERO);
114	        }
115	        for (Claim c : claims.list(sheetId)) {
116	            Person p = byId.get(c.getPersonId());
117	            if (p == null || !counts(c, p, today) || c.getDate().isBefore(from) || c.getDate().isAfter(to)) {
118	                continue;
119	            }
120	            BigDecimal figure = late.due(c, figure(c, p.gradeOn(c.getDate()), sheetRates, late));
121	            if (figure != null) {
122	                totals.merge(p.getId(), figure, BigDecimal::add);
123	            }
124	        }
125	        return totals;
126	    }
