295	    /** The claim's late charge on its figure (zero when it is not overdue, is deferred past today, or has no figure). */
296	    public BigDecimal on(Claim claim, BigDecimal figure) {
297	        BigDecimal none = BigDecimal.ZERO.setScale(2);
298	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
299	            return none;
300	        }
301	        return onAsOpen(claim, figure);
302	    }
303	    /** The late charge the claim would have on its figure were it OPEN. */
304	    public BigDecimal onAsOpen(Claim claim, BigDecimal figure) {
305	        BigDecimal none = BigDecimal.ZERO.setScale(2);
306	        if (figure == null || claim.isCorrection()) {
307	            return none;
308	        }
309	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
310	        long periods = overdue > 0 ? overdue / 30 : 0;
311	        if (periods == 0) {
312	            return none;
313	        }
314	        return figure.multiply(settings.latePct(claim.getDate())).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
315	                .setScale(2, rounding(claim));
316	    }
