318	    public BigDecimal due(Claim claim, BigDecimal figure) {
319	        return figure == null ? null : figure.setScale(2).add(on(claim, figure));
320	    }
321	    /** The figure with the late charge the claim would have were it OPEN; null without a figure. */
322	    public BigDecimal dueAsOpen(Claim claim, BigDecimal figure) {
323	        return figure == null ? null : figure.setScale(2).add(onAsOpen(claim, figure));
