932	/**
933	 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
934	 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
935	 * figure its last statement bound it to, else its amount times the rate in force on the claim's date of its
936	 * person's grade in force on that date (rounded as the claim rounds by the sheet's policy date, and at least the sheet's floor in force on the claim's date; none without a rate). The due-total is the counting claims' figures
937	 * added up, each with its late charge on top while it is overdue (the charge is never bound); n/a
938	 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure; at most the sheet's cap in force on its today.
939	 */
940	public class TakeStatement {
941	    public void take(@Val Person person, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
942	            SettingRepository settings, StatementRepository statements, Out<Statement> taken) {
943	        String sheetId = person.getSheetId();
944	        LocalDate today = sheets.today(sheetId);
945	        LateCharge late = settings.lateCharge(sheetId, today);
946	        List<Claim> mine = claims.listOf(sheetId, person.getId());
947	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
948	        boolean kept = false;
949	        int counted = 0;
950	        for (Claim c : mine) {
951	            // OPEN and PENDING claims dated within a hold do not count, unless the last statement bound them; a claim
952	            // deferred past today does not count and is left unbound.
953	            if (!c.getStatus().counts() || Rollup.held(c, person) || c.isDeferredOn(today)) {
954	                claims.bind(c.getId(), false, null);
955	                continue;
956	            }
957	            counted++;
958	            kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
959	            BigDecimal figure = figure(c, person, rates, late);
960	            // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
961	            // dated on or before today, whose rate may have ended since.
962	            kept |= figure != null && (!person.gradeOn(c.getDate()).equals(person.getGrade()) || !c.getDate().isAfter(today));
963	            if (figure != null) {
964	                sum = sum.add(late.due(c, figure));
965	            }
966	            claims.bind(c.getId(), true, figure);
967	        }
968	        BigDecimal dueTotal = SettingRepository.capped(
969	                kept || rates.find(sheetId, person.getGrade(), today) != null ? sum : null, late.settings().cap(today));
970	        statements.insert(sheetId, person.getId(), dueTotal, today);
971	        person.setStatements(new Statements(person.getStatements().count() + 1, dueTotal, today));
972	        taken.set(new Statement(dueTotal, counted));
973	    }
974	    private static BigDecimal figure(Claim claim, Person person, RateRepository rates, LateCharge late) {
975	        if (claim.getSettledDue() != null) {
976	            return claim.getSettledDue();
977	        }
978	        if (claim.isBound()) {
979	            return claim.getStatedDue();
980	        }
981	        BigDecimal rate = rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
982	        return claim.figureAt(rate, late.settings().floor(claim.getDate()), late.rounding(claim));
983	    }
984	}
