1177	/**
1178	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
1179	 * so tests can assert side-effects by reading that file — the second test-assertion channel
1180	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
1181	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
1182	 *
1183	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
1184	 * SYNC) so a test reads the record immediately.
1185	 */
1186	@Service
1187	public class Audit {
1188	    private final Path file;
1189	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
1190	        this.file = Path.of(path);
1191	    }
1192	    /** Append one audit record. Tests assert the exact line(s) in the file. */
1193	    public synchronized void record(String entry) {
1194	        try {
1195	            Path parent = file.toAbsolutePath().getParent();
1196	            if (parent != null) {
1197	                Files.createDirectories(parent);
1198	            }
1199	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
1200	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
1201	        } catch (IOException e) {
1202	            throw new UncheckedIOException(e);
1203	        }
1204	    }
